WITH scored AS (SELECT *, NTILE(4) OVER (PARTITION BY region, city ORDER BY sqft, id) AS sqft_bucket, NTILE(4) OVER (PARTITION BY region ORDER BY sqft DESC, id) AS sqft_bucket_2, AVG(sqft) OVER (PARTITION BY city, region) AS city_avg_sqft, ROW_NUMBER() OVER (PARTITION BY city ORDER BY opened_date, id) AS row_seq, CUME_DIST() OVER (PARTITION BY region ORDER BY sqft DESC NULLS LAST) AS sqft_cume_dist FROM stores) SELECT DATE_TRUNC('WEEK', opened_date) AS week_start, COUNT(*) FILTER (WHERE region = 'Central') AS central_rows, SUM(sqft_cume_dist) FILTER (WHERE region = 'Central') AS central_total_sqft_cume_dist, SORT_ARRAY(COLLECT_SET(region)) AS region_list, COUNT(DISTINCT city) AS distinct_cities, ROUND(SUM(city_avg_sqft) / NULLIF(COUNT(CASE WHEN city = 'London' THEN 1 END), 0), 2) AS city_avg_sqft_per_london, COUNT(CASE WHEN region = 'Central' THEN 1 END) AS central_count FROM scored GROUP BY DATE_TRUNC('WEEK', opened_date) HAVING COUNT(DISTINCT city) > 1 ORDER BY week_start DESC NULLS LAST
